"""Render-only Kaizen Calm proposal. Never touches installed theme files."""
from pathlib import Path
import re, json, hashlib, shutil
ROOT = Path(__file__).resolve().parent
REPO = ROOT.parents[1]
DEPLOYED = Path('/opt/data/desktop-plugins/00-kaizen-theme/plugin.js')
text = DEPLOYED.read_text()
base_match = re.search(r'const themeCSS = ("(?:[^"\\]|\\.)*");', text)
chat_match = re.search(r'customCSS: themeCSS \+ ("(?:[^"\\]|\\.)*")', text)
assert base_match is not None and chat_match is not None, 'Installed theme literal format changed'
base = json.loads(base_match.group(1))
chat = json.loads(chat_match.group(1))
ROOT.mkdir(parents=True, exist_ok=True)
(ROOT / 'baseline.css').write_text(base + '\n' + chat)
shutil.copyfile(REPO / 'packages/theme/assets/hanken-grotesk-variable.ttf', ROOT/'hanken.ttf')
assets = Path('/opt/hermes/apps/desktop/dist-webapp/assets')
links = ''.join(f'<link rel="stylesheet" href="{p.as_uri()}">' for pat in ['main-*.css','capabilities-*.css'] for p in assets.glob(pat))
