for mode in ['light','dark']:
 for variant in ['current','proposal']:
  out=html
  for old,new in {'MODE':mode,'LINKS':links,'COMMON':common,'PROPOSAL':'<link rel="stylesheet" href="proposal.css">' if variant=='proposal' else '', 'VARIANT':variant,'LABEL':'PROPOSED · WODAY-INSPIRED' if variant=='proposal' else 'CURRENT · SOURCE-BASED RECONSTRUCTION','NAV':nav,'SESSIONS':sessions}.items():out=out.replace(old,new)
  for tag,key in [('MENU','menu'),('SEARCH','search'),('PLUS','plus'),('FILES','files'),('GEAR','gear'),('CLIP','clip'),('ARROW','arrow')]:out=out.replace(tag,icon(key))
  (ROOT/f'{variant}-{mode}.html').write_text(out)
